#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
* Tip: For syntax highlighting, paste the code here:
* https://shadered.org/app?fork=4Y3P9GQID0
*/ 
precision highp float;
out vec4 O;
uniform vec2 resolution;
uniform float time;
uniform vec2 move;
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define S smoothstep
#define N normalize
#define MN min(R.x,R.y)
#define hue(a) (.5+.5*sin(6.28318*(a)+vec3(1.57,.39,.0)))
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define cmul(a,b) vec2(a.x*b.x-a.y*b.y,a.x*b.y+b.x*a.y)
struct Material {
	float dist;
	vec3 col;
	float rough;
	int id;
	bool hit;
};
float pmod(inout vec2 p, float n) {
  float angle=6.28318/n,
  a=atan(p.y,p.x)+angle/2.,
  r=length(p),
  c=floor(a/angle);
  a=mod(a,angle)-angle/2.;
  p=vec2(cos(a),sin(a))*r;
  if (abs(c) >= (n/2.)) c=abs(c);
  return c;
}
float bmap( vec3 p ) {
	p=vec3(p.x+p.z*.5, p.y, p.x-p.z);
	p=vec3(p.x+p.y, p.x-p.y, p.z);
	p=fract(p*3.99);
	float d=length(p-.5);
	d=d*d;
	return -d*4e-3;
}
vec3 smin(vec3 a, vec3 b, float k) {
	vec3 h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
float swirls(vec3 p) {
	vec3 c=p;
	float d=.1;
	for (float i=.0; i<5.; i++) {
		p=smin(p,-p,-.01)/dot(p,p)-.7;
		p.yz=cmul(p.yz,p.yz);
		p=p.zxy;
		d+=exp(-19.*abs(dot(p,c)));
	}
	return d;
}
void anim(inout vec3 p) {
	float k=S(-.05,1.,min(.1*mod(T,22.),2.));
	p.yz*=rot(min(k*.2,1.));
	p.xz*=rot(.1/min(k*1.2,1.)+k);
}
vec3 marchswirls(vec3 p, vec3 rd) {
	anim(p); anim(rd);
	vec3 col=vec3(0);
	float c=.0, t=.0;
	for (float i=.0; i<60.; i++) {
		t+=exp(-t*.65)*exp(-c*1.05);
		c=swirls(p+rd*t);
		col+=c*hue(.1*T-dot(p,p)+c)*.03;
	}
	return col;
}
Material matmin(Material a, Material b) {
	if (a.dist<b.dist) return a;
	return b;
}
Material satelites(vec3 p) {
	p.y-=.4;
	float id=pmod(p.xz,40.);
	p.x-=3.5;
	p.y=abs(p.y)-.2;
	p.xz*=rot(T+pow(sin((id/40.)*(6.28318/40.)),2.));
	p=abs(p)-vec3(.0125,.15,.125);
	float d=length(max(p,.0))+min(.0,max(max(p.x,p.y),p.z))-.01;
	d+=bmap(p*12.)*.2;
	d*=.8;
	return Material(d,hue(-.1+dot(p.xz,p.xz)*50.),.01,2,false);
}
Material bottom(vec3 p) {
	float d=p.y+.0,b=bmap(p.zyx)*S(9.,.0,min(dot(p.xz,p.xz),6.));
	d+=b;
	d=smin(d,-(length(p)-1.1),-1.);
	return Material(d,hue(vec3(.7,1,.4)),.6,0,false);
}
Material sphere(vec3 p) {
	p.y-=.4;
	float d=length(p)-1.36;
	return Material(d,vec3(0),.5,1,false);
}
Material map(vec3 p) {
	Material a=bottom(p),
	b=satelites(p);
	a=matmin(a,b);
	b=sphere(p);
	a=matmin(a,b);
	return a;
}
Material march(inout vec3 p, vec3 rd) {
	Material mat;
	float dd=.0;
	for (int i; i++<400;) {
		mat=map(p);
		if (abs(mat.dist)<1e-3) {
			mat.hit=true;
			break;
		}
		if (dd>5e2) break;
		p+=rd*mat.dist;
		dd+=mat.dist;
	}
	return mat;
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h).dist+
		k.yxy*map(p+k.yxy*h).dist+
		k.yyx*map(p+k.yyx*h).dist+
		k.xxx*map(p+k.xxx*h).dist
	);
}
float shadow(vec3 p, vec3 lp, out vec3 mat) {
	if (p.y>2.) return 1.;
	float shd=1., maxd=length(lp-p);
	vec3 l=N(lp-p);
	for (float i=1e-2; i<maxd;) {
		Material d=map(p+l*i);
		if (abs(d.dist)<1e-2) {
			shd=.0;
			mat=d.col;
			break;
		}
		shd=min(shd,64.*d.dist/i);
		i+=d.dist;
	}
	return shd;
}
float calcAO(vec3 p, vec3 n) {
	float occ=.0, sca=1.;
	for (float i=.0; i<5.; i++) {
		float
		h=.01+i*.09,
		d=map(p+h*n).dist;
		occ+=(h-d)*sca;
		sca*=.55;
		if (occ>.35) break;
	}
	return clamp(1.-3.*occ,.0,1.)*(.5+.5*n.y);
}
float getsss(vec3 p, vec3 rd, float dist, float k) {
	float ddist = dist*k;
  return
  	clamp(map(p+rd*dist).dist/dist,.0, 1.)+
  	clamp(map(p+rd*ddist).dist/ddist,.0, 1.);
}
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
vec3 sky(vec2 p, bool anim) {
	p.x-=.17-(anim?2e-4*T:.0);
	p*=500.;
	vec2 id=floor(p), gv=fract(p)-.5;
	float n=rnd(id), d=length(gv);
	if (n<.95) return vec3(0);
	return hue(3.14*rnd(id))*vec3(S(3e-2*n,1e-3*n,d*d));
}
vec3 render(inout vec3 p, vec3 rd, out Material mat) {
	vec3 col=vec3(0);
	mat=march(p,rd);
	if (mat.hit) {
		vec3 n=norm(p), lp=vec3(sin(T*.2)*3.,2.5,cos(T*.5)*2.-4.), l=N(lp-p),
		smat;
		float dif=clamp(dot(l,n),.0,1.),
		fres=pow(clamp(1.+dot(rd,n),.0,1.),5.),
		spec=pow(clamp(dot(reflect(rd,n),l),.0,1.),8.),
		ld=max(distance(lp,p),1e-3),
		shd=clamp(shadow(p+n*5e-2,lp,smat),.0,1.),
		ao=calcAO(p,n),
		sss=clamp(getsss(p,rd,5.,.3),.0,1.);
		// reflections
		const float k=160.;
		vec3 q=p;
		float id=pmod(q.xz,k);
		q.x-=3.;
		q.xz*=rot(2.*T-pow(sin((id/k)*(6.28318/k)),2.));
		vec3 ll=N(q-p);
		float hl=clamp(dot(n,ll),.0,1.);
		if (mat.id==1) {
			col+=marchswirls((p-vec3(0,.4,0))*5.2,refract(rd,n,.9));
		}
		col+=pow(hl,8.)*.25+pow(hl,64.)*.5;
		col+=clamp(.6*mat.col+.4*S(.3,1.,ao*sqrt(dif))*mat.col,.0,1.);
		col+=fres*vec3(1,.95,.8)*S(1.,.0,ao);
		col=mix(mix(col*.75,smat*.2,1./(1.+ld*.5+ld*ld*5e-1)),col,max(shd,.6*sqrt(ao)));
		col+=.2*clamp(dot(N(vec3(0,10,0)-p),n),.0,1.)*S(1.,.0,dot(vec3(.21,.71,.07),mat.col));
		col+=S(1.,.0,mat.rough*sss)*clamp(spec*vec3(1,.95,.8)+spec*.5*mat.col,.0,1.);
		col*=1./(1.+ld*125e-4+ld*ld*25e-3);
	} else {
		col=mix(vec3(0),hue(-.5+tanh(dot(rd.xz*.02,rd.xz*.1))),S(.0,1.,dot(rd.xy,rd.yz)));
		vec2 sn=.5+vec2(atan(rd.x,rd.z),atan(length(rd.xz),rd.y))/6.28318;
		sn*=.5;
		col=mix(col,hue(.0),vec3(sky(sn,false)+sky(2.+sn*2.,false)+sky(9.9+sn*3.,false)));
	}
	return col;
}
void cam(inout vec3 p) {
	float t=.2*T;
	p.yz*=rot(sin(move.y*6.3/MN-.6+cos(1.+t*.5))*.5+.65);
	p.xz*=rot(-move.x*6.3/MN-.56+.1*sin(t));
	p.xy*=rot(-.1*sin(t));
}
void main(void) {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,R.x>R.y?-7:-5),
	rd=N(vec3(uv,1.2));
	cam(p); cam(rd);
	Material mat0, mat1;
	col=render(p,rd,mat0);
	vec3 q=p;
	if (mat0.hit) {
		vec3 n=norm(p);
		p+=5e-2*n;
		float fres=pow(clamp(1.+dot(rd,n),.0,1.),5.);
		vec3 c=render(p,reflect(rd,n),mat1);
		c=mix(c,vec3(0),S(1.0,40.,min(dot(q.xz,q.xz),40.)));
		col=mix(col,c,fres);
		col=mix(col,c,(1.-fres)*S(1.,.0,mat0.rough)*.3);
	}
	col=tanh(col);
	col=mix(vec3(0),col,min(S(.0,1.,time*.3),1.));
	O=vec4(col,1);
}

